'use strict';

const DEFAULT_DELIMITER = ',';
const DEFAULT_EOL = '\r\n';
const ALLOWED_EOLS = ['\r\n', '\n'];

const MAX_DESCRIBED_STRING = 32;

/** Short human-readable description of a value for error messages. */
function describe(value) {
  if (value === null) return 'null';
  if (Array.isArray(value)) return 'an array';
  switch (typeof value) {
    case 'string':
      return value.length > MAX_DESCRIBED_STRING
        ? `${JSON.stringify(value.slice(0, MAX_DESCRIBED_STRING))}...`
        : JSON.stringify(value);
    case 'object':
      return 'an object';
    case 'function':
      return 'a function';
    case 'symbol':
      return value.toString();
    case 'bigint':
      return `${value}n`;
    default:
      return String(value);
  }
}

function assertOptionsObject(options, fnName) {
  if (options === null || typeof options !== 'object' || Array.isArray(options)) {
    throw new TypeError(`${fnName}: options must be an object, received ${describe(options)}`);
  }
}

function resolveDelimiter(value, fnName) {
  if (value === undefined) return DEFAULT_DELIMITER;
  if (
    typeof value !== 'string' ||
    value.length !== 1 ||
    value === '"' ||
    value === '\r' ||
    value === '\n'
  ) {
    throw new TypeError(
      `${fnName}: options.delimiter must be a single character other than '"', CR or LF, received ${describe(value)}`,
    );
  }
  return value;
}

function resolveBoolean(value, name, fnName) {
  if (value === undefined) return false;
  if (typeof value !== 'boolean') {
    throw new TypeError(`${fnName}: options.${name} must be a boolean, received ${describe(value)}`);
  }
  return value;
}

function resolveEol(value, fnName) {
  if (value === undefined) return DEFAULT_EOL;
  if (!ALLOWED_EOLS.includes(value)) {
    throw new TypeError(`${fnName}: options.eol must be '\\r\\n' or '\\n', received ${describe(value)}`);
  }
  return value;
}

/** Validates `parse`/`createParser` options. Unknown keys are ignored. */
function resolveParseOptions(options, fnName) {
  assertOptionsObject(options, fnName);
  return {
    delimiter: resolveDelimiter(options.delimiter, fnName),
    header: resolveBoolean(options.header, 'header', fnName),
    skipEmptyLines: resolveBoolean(options.skipEmptyLines, 'skipEmptyLines', fnName),
  };
}

/**
 * Validates `stringify` options. Unknown keys (such as `skipEmptyLines`) are
 * ignored so one options object can be shared with `parse`.
 */
function resolveStringifyOptions(options, fnName) {
  assertOptionsObject(options, fnName);
  const { header } = options;
  if (header !== undefined && header !== false) {
    if (!Array.isArray(header) || header.length === 0) {
      throw new TypeError(
        `${fnName}: options.header must be a non-empty array of column names, received ${describe(header)}`,
      );
    }
    header.forEach((name, index) => {
      if (typeof name !== 'string') {
        throw new TypeError(
          `${fnName}: options.header[${index}] must be a string, received ${describe(name)}`,
        );
      }
    });
  }
  return {
    delimiter: resolveDelimiter(options.delimiter, fnName),
    eol: resolveEol(options.eol, fnName),
    header: Array.isArray(header) ? header.slice() : null,
  };
}

module.exports = { describe, resolveParseOptions, resolveStringifyOptions };
'use strict';

/**
 * Thrown for malformed CSV input. `line` and `column` are 1-based; columns
 * count UTF-16 code units and a leading byte order mark is not counted.
 */
class CsvError extends Error {
  /**
   * @param {string} message Description of the problem, without the position.
   * @param {number} line 1-based line of the offending input.
   * @param {number} column 1-based column (UTF-16 code units).
   * @param {string} code Stable machine-readable identifier, e.g. `UNCLOSED_QUOTE`.
   */
  constructor(message, line, column, code) {
    super(`${message} at line ${line}, column ${column}`);
    this.name = 'CsvError';
    this.line = line;
    this.column = column;
    this.code = code;
  }
}

/** Values of `CsvError#code`. */
const CsvErrorCode = Object.freeze({
  UNCLOSED_QUOTE: 'UNCLOSED_QUOTE',
  UNEXPECTED_CHARACTER: 'UNEXPECTED_CHARACTER',
  DUPLICATE_HEADER: 'DUPLICATE_HEADER',
  FIELD_COUNT_MISMATCH: 'FIELD_COUNT_MISMATCH',
});

module.exports = { CsvError, CsvErrorCode };
'use strict';

const { CsvError, CsvErrorCode } = require('./errors');
const { describe, resolveParseOptions } = require('./options');

const QUOTE = 0x22;
const CR = 0x0d;
const LF = 0x0a;
const BOM = 0xfeff;

// Nothing of the current record has been read. A line break here is an empty line.
const RECORD_START = 0;
// The next character is the first of a field; its position is already recorded.
const FIELD_START = 1;
const UNQUOTED = 2;
const QUOTED = 3;
// A `"` was read inside a quoted field. The next character decides whether it
// was the first half of `""` or the closing quote, and may be in the next chunk.
const AFTER_QUOTE = 4;

/**
 * Incremental state machine behind both `parse` and `createParser`. It keeps
 * only the current field and record, so each chunk is read exactly once.
 */
class StreamParser {
  constructor(options, fnName) {
    const { delimiter, header, skipEmptyLines } = resolveParseOptions(options, fnName);
    this.delimiter = delimiter.charCodeAt(0);
    this.headerMode = header;
    this.skipEmptyLines = skipEmptyLines;
    this.columns = null;
    // Non-null only while the header record is being read.
    this.seenColumns = header ? new Set() : null;

    this.state = RECORD_START;
    this.sawInput = false;
    this.closedReason = null;
    // Position of the next unread character.
    this.line = 1;
    this.column = 1;
    // The last character read was a CR, so an LF next completes a CRLF.
    this.afterCR = false;

    this.record = [];
    this.field = '';
    this.fieldLine = 1;
    this.fieldColumn = 1;
    this.recordLine = 1;
    this.output = [];
  }

  write(chunk) {
    this.assertOpen('write');
    try {
      if (typeof chunk !== 'string') {
        throw new TypeError(`write: chunk must be a string, received ${describe(chunk)}`);
      }
      this.consume(chunk);
      return this.takeOutput();
    } catch (err) {
      this.closedReason = 'an earlier call threw';
      throw err;
    }
  }

  end() {
    this.assertOpen('end');
    try {
      this.finish();
      this.closedReason = 'end() was already called';
      return this.takeOutput();
    } catch (err) {
      this.closedReason = 'an earlier call threw';
      throw err;
    }
  }

  assertOpen(method) {
    if (this.closedReason !== null) {
      throw new Error(`${method}: the parser is closed because ${this.closedReason}`);
    }
  }

  takeOutput() {
    const records = this.output;
    this.output = [];
    return records;
  }

  consume(chunk) {
    const length = chunk.length;
    let i = 0;
    if (!this.sawInput) {
      if (length === 0) return;
      this.sawInput = true;
      if (chunk.charCodeAt(0) === BOM) i = 1;
    }
    while (i < length) {
      switch (this.state) {
        case RECORD_START:
          i = this.readRecordStart(chunk, i);
          break;
        case FIELD_START:
          i = this.readFieldStart(chunk, i);
          break;
        case UNQUOTED:
          i = this.readUnquoted(chunk, i);
          break;
        case QUOTED:
          i = this.readQuoted(chunk, i);
          break;
        default:
          i = this.readAfterQuote(chunk, i);
          break;
      }
    }
  }

  finish() {
    switch (this.state) {
      case RECORD_START:
        // Empty input, or the input ended with a line break.
        return;
      case QUOTED:
        throw new CsvError(
          'Unclosed quoted field',
          this.fieldLine,
          this.fieldColumn,
          CsvErrorCode.UNCLOSED_QUOTE,
        );
      default:
        this.endField();
        this.endRecord();
    }
  }

  readRecordStart(chunk, i) {
    const c = chunk.charCodeAt(i);
    if (this.afterCR) {
      this.afterCR = false;
      if (c === LF) return i + 1;
    }
    this.recordLine = this.line;
    this.markFieldStart();
    if (c === CR || c === LF) {
      this.advanceLine(c);
      if (!this.skipEmptyLines) {
        this.endField();
        this.endRecord();
      }
      return i + 1;
    }
    this.state = FIELD_START;
    return i;
  }

  readFieldStart(chunk, i) {
    if (chunk.charCodeAt(i) === QUOTE) {
      this.column++;
      this.state = QUOTED;
      return i + 1;
    }
    this.state = UNQUOTED;
    return i;
  }

  readUnquoted(chunk, i) {
    const { delimiter } = this;
    const length = chunk.length;
    let j = i;
    while (j < length) {
      const c = chunk.charCodeAt(j);
      if (c === delimiter || c === CR || c === LF) break;
      j++;
    }
    if (j > i) {
      this.field += chunk.slice(i, j);
      this.column += j - i;
    }
    if (j === length) return j;
    this.terminateField(chunk.charCodeAt(j));
    return j + 1;
  }

  readQuoted(chunk, i) {
    const length = chunk.length;
    let { line, column, afterCR } = this;
    let j = i;
    for (; j < length; j++) {
      const c = chunk.charCodeAt(j);
      if (c === QUOTE) break;
      if (c === CR) {
        line++;
        column = 1;
        afterCR = true;
      } else if (c === LF) {
        if (!afterCR) {
          line++;
          column = 1;
        }
        afterCR = false;
      } else {
        column++;
        afterCR = false;
      }
    }
    if (j > i) this.field += chunk.slice(i, j);
    this.line = line;
    this.column = column;
    this.afterCR = afterCR;
    if (j === length) return j;
    this.column++;
    this.afterCR = false;
    this.state = AFTER_QUOTE;
    return j + 1;
  }

  readAfterQuote(chunk, i) {
    const c = chunk.charCodeAt(i);
    if (c === QUOTE) {
      this.field += '"';
      this.column++;
      this.state = QUOTED;
      return i + 1;
    }
    if (c === this.delimiter || c === CR || c === LF) {
      this.terminateField(c);
      return i + 1;
    }
    throw new CsvError(
      `Unexpected character ${JSON.stringify(chunk[i])} after a closing quote`,
      this.line,
      this.column,
      CsvErrorCode.UNEXPECTED_CHARACTER,
    );
  }

  /** Ends the current field at `c`, which is the delimiter, CR or LF. */
  terminateField(c) {
    this.endField();
    if (c === this.delimiter) {
      this.column++;
      this.markFieldStart();
      this.state = FIELD_START;
      return;
    }
    this.advanceLine(c);
    this.endRecord();
    this.state = RECORD_START;
  }

  advanceLine(c) {
    this.line++;
    this.column = 1;
    this.afterCR = c === CR;
  }

  markFieldStart() {
    this.fieldLine = this.line;
    this.fieldColumn = this.column;
  }

  endField() {
    const value = this.field;
    this.field = '';
    if (this.seenColumns !== null) {
      if (this.seenColumns.has(value)) {
        throw new CsvError(
          `Duplicate header name ${JSON.stringify(value)}`,
          this.fieldLine,
          this.fieldColumn,
          CsvErrorCode.DUPLICATE_HEADER,
        );
      }
      this.seenColumns.add(value);
    }
    this.record.push(value);
  }

  endRecord() {
    const record = this.record;
    this.record = [];
    if (!this.headerMode) {
      this.output.push(record);
      return;
    }
    if (this.columns === null) {
      this.columns = record;
      this.seenColumns = null;
      return;
    }
    this.output.push(this.toObject(record));
  }

  toObject(record) {
    const { columns } = this;
    if (record.length !== columns.length) {
      throw new CsvError(
        `Expected ${columns.length} ${plural(columns.length, 'field')} to match the header, found ${record.length}`,
        this.recordLine,
        1,
        CsvErrorCode.FIELD_COUNT_MISMATCH,
      );
    }
    const object = {};
    for (let k = 0; k < columns.length; k++) {
      const key = columns[k];
      if (key === '__proto__') {
        // Plain assignment would replace the prototype instead of adding a column.
        Object.defineProperty(object, key, {
          value: record[k],
          writable: true,
          enumerable: true,
          configurable: true,
        });
      } else {
        object[key] = record[k];
      }
    }
    return object;
  }
}

function plural(count, word) {
  return count === 1 ? word : `${word}s`;
}

/**
 * @typedef {object} ParseOptions
 * @property {string} [delimiter=','] One UTF-16 code unit other than `"`, CR or LF.
 * @property {boolean} [header=false] Use the first record as column names and return objects.
 * @property {boolean} [skipEmptyLines=false] Drop lines that contain no characters at all.
 */

/**
 * Parses a complete CSV document.
 *
 * @param {string} text
 * @param {ParseOptions} [options]
 * @returns {Array<string[]> | Array<Record<string, string>>}
 * @throws {TypeError} If `text` is not a string or an option is invalid.
 * @throws {CsvError} If the input is malformed.
 */
function parse(text, options = {}) {
  if (typeof text !== 'string') {
    throw new TypeError(`parse: text must be a string, received ${describe(text)}`);
  }
  const parser = new StreamParser(options, 'parse');
  const records = parser.write(text);
  for (const record of parser.end()) records.push(record);
  return records;
}

/**
 * @typedef {object} CsvStreamParser
 * @property {(chunk: string) => Array<string[] | Record<string, string>>} write
 *   Feeds the next piece of input and returns the records it completed.
 * @property {() => Array<string[] | Record<string, string>>} end
 *   Signals the end of input and returns the remaining records.
 */

/**
 * Creates a parser for input that arrives in pieces. Records and errors are
 * the same as `parse` on the concatenated input, wherever the chunks split.
 * Once `end()` has been called or either method has thrown, both methods throw.
 *
 * @param {ParseOptions} [options]
 * @returns {CsvStreamParser}
 * @throws {TypeError} If an option is invalid.
 */
function createParser(options = {}) {
  const parser = new StreamParser(options, 'createParser');
  return {
    write: (chunk) => parser.write(chunk),
    end: () => parser.end(),
  };
}

module.exports = { parse, createParser };
# csv-rfc4180

A CSV parser, streaming parser and serializer for Node.js. It has no dependencies and is written in CommonJS.

```js
const { parse, createParser, stringify, CsvError } = require('./src/csv');

parse('name,age\r\nAda,36\r\n');
// [['name', 'age'], ['Ada', '36']]

parse('name,age\nAda,36\n', { header: true });
// [{ name: 'Ada', age: '36' }]

stringify([['a,b', 'say "hi"'], ['']]);
// '"a,b","say ""hi"""\r\n""\r\n'
```

Requires Node.js 18 or later. Run the tests with `npm test`. `npm run lint` checks that every file parses.

## API

### `parse(text, options = {})`

Parses a whole document and returns an array of records. Each record is an array of strings, or an object when `header` is `true`.

| Option | Default | Meaning |
| --- | --- | --- |
| `delimiter` | `','` | Field separator. Must be one character (one UTF-16 code unit) other than `"`, CR or LF. |
| `header` | `false` | Use the first record as column names and return one object per later record. |
| `skipEmptyLines` | `false` | Drop lines that contain no characters. |

Parsing rules:

- Records end at CRLF, LF or CR, and one input can mix them.
- A leading byte order mark (`U+FEFF`) is dropped. A BOM anywhere else is kept.
- A field that starts with `"` is quoted. Inside it, delimiters, CR and LF are literal and `""` is one `"`. The closing quote must be followed by a delimiter, a line break or the end of input.
- In a field that does not start with `"`, a `"` is an ordinary character.
- Fields are never trimmed.
- A single line break at the end of the input does not start a record. Any other empty line is the record `['']`, unless `skipEmptyLines` is set. So `'a\n'` gives `[['a']]`, `'a\n\n'` gives `[['a'], ['']]` and `'\n'` gives `[['']]`.
- In header mode, duplicate column names are an error, and so is a later record whose field count differs from the header's. A document with only a header returns `[]`.

### `createParser(options = {})`

Returns `{ write(chunk), end() }` for input that arrives in pieces. It takes the same options as `parse`.

```js
const parser = createParser({ header: true });
parser.write('id,na');        // []
parser.write('me\r\n1,Ada\r'); // [{ id: '1', name: 'Ada' }]
parser.write('\n2,Alan');      // []
parser.end();                  // [{ id: '2', name: 'Alan' }]
```

- `write(chunk)` takes a string and returns the records that this chunk completed. A record comes back from the `write` whose chunk contains the line break that ends it. A record ended by a CR is returned right away, and an LF at the start of the next chunk is treated as the second half of that CRLF.
- `end()` returns the last record, if the input did not end with a line break.
- After `end()`, or after either method has thrown (including a `TypeError` for a non-string chunk), both methods throw an `Error`.

Wherever the chunks split the input, the records and any `CsvError` (including its `line` and `column`) are the same as `parse` returns for the whole input. `parse` is implemented as one `write` followed by `end`, so the two share a single code path. The parser keeps only the field and record it is currently reading. Every chunk is scanned once, so time and memory grow linearly with the input.

### `stringify(rows, options = {})`

Serializes an array of records. Every record, including the last, ends with `eol`. An empty `rows` array gives `''`.

| Option | Default | Meaning |
| --- | --- | --- |
| `delimiter` | `','` | Validated the same way as in `parse`. |
| `eol` | `'\r\n'` | `'\r\n'` or `'\n'`. |
| `header` | none | A non-empty array of column names. It is written as the first row, and records may then be objects. |

- Strings are written unchanged. Numbers and booleans go through `String()`. `null` and `undefined` become empty fields. Any other value throws a `TypeError` that names its position, e.g. `rows[3][1]`.
- A field is quoted when it contains the delimiter, `"`, CR or LF, or when it starts or ends with a space. Each `"` inside it is doubled.
- A record whose only field is empty is written as `""`. Without the quotes it would be an empty line, which `parse` reads as `['']` and `skipEmptyLines` drops.
- With `header`, an object record is written in header order. A missing key becomes an empty field. Only own properties are read, so a column named `toString` does not pick up `Object.prototype.toString`. Array records are still accepted and written as given.

`parse(stringify(rows, opts), opts)` returns `rows` for any rows that are non-empty arrays of strings, with or without `skipEmptyLines`. `stringify` ignores `skipEmptyLines` and `parse` ignores `eol`, so one options object works for both.

### `CsvError`

A subclass of `Error`, thrown for malformed input. Its properties:

- `line` and `column`: 1-based. Lines are counted by the same line breaks as records, including line breaks inside quoted fields. Columns count UTF-16 code units.
- `code`: one of the values below.

| `code` | Cause | Position |
| --- | --- | --- |
| `UNCLOSED_QUOTE` | A quoted field never closes. | The opening `"`. |
| `UNEXPECTED_CHARACTER` | A closing `"` is followed by something other than a delimiter or line break. | That character. |
| `DUPLICATE_HEADER` | A column name repeats (header mode). | Where the second occurrence's field starts. |
| `FIELD_COUNT_MISMATCH` | A record has more or fewer fields than the header (header mode). | That record's first line, column 1. |

If the input has several errors, the parser throws the first one it reaches reading left to right.

## Assumptions

The specification leaves a few cases open. These are the choices made:

- **The delimiter is one UTF-16 code unit.** Astral characters such as emoji are two code units and are rejected with a `TypeError`. This keeps column numbers and chunk handling in code units, the same unit the error positions use.
- **A leading BOM is not counted as a column.** For `'﻿"abc'`, the unclosed-quote error is at column 1.
- **A duplicate header name is reported as soon as its field ends.** So `a,a,"b` reports the duplicate at column 3, not the unclosed quote that comes later. The field-count check waits for the end of the record, as specified.
- **Only `undefined` means "use the default".** `null` or a wrong type for any option throws a `TypeError`. `header` and `skipEmptyLines` must be booleans in `parse`. Unknown option keys are ignored.
- **In `stringify`, a single `null` or `undefined` field is also written as `""`.** Its serialized text is empty, so the same ambiguity with an empty line applies.
- **In `stringify`, the output never starts with a BOM.** If the first field of the first line starts with `U+FEFF`, or the first field is empty and the delimiter is `U+FEFF`, that field is quoted. Otherwise `parse` would drop the BOM and the round trip would lose it.
- **`stringify([], { header })` writes the header row.** "No rows gives `''`" applies when there is no header. The header-only output parses back to `[]` in header mode.
- **An empty record `[]` in `stringify` becomes an empty line.** The round-trip guarantee covers only non-empty records.
- **A header column named `__proto__` becomes an own property.** Parsed objects keep `Object.prototype`, so they compare equal to object literals, and `__proto__` is defined with `Object.defineProperty` so it cannot replace the prototype.

## Layout

```
src/csv.js        public entry point
src/parser.js     state machine behind parse and createParser
src/stringify.js  serializer
src/options.js    option validation shared by both
src/errors.js     CsvError
test/             node:test suites: parse, errors, stream, stringify, roundtrip
scripts/          dependency-free syntax check used by `npm run lint`
```

The tests use only `node:test` and `node:assert`. `test/stream.test.js` checks every one- and two-point split of a corpus of valid and invalid inputs against `parse`. `test/roundtrip.test.js` runs seeded random round trips over several delimiters, both line endings and both `skipEmptyLines` settings.
'use strict';

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const { parse, createParser, CsvError } = require('../src/csv');

/** Runs `fn` and captures either its result or the identifying fields of its error. */
function outcome(fn) {
  try {
    return { records: fn() };
  } catch (err) {
    return {
      error: { name: err.name, line: err.line, column: err.column, code: err.code, message: err.message },
    };
  }
}

function parseInChunks(chunks, options) {
  const parser = createParser(options);
  const records = [];
  for (const chunk of chunks) records.push(...parser.write(chunk));
  records.push(...parser.end());
  return records;
}

function splitAt(text, points) {
  const chunks = [];
  let previous = 0;
  for (const point of points) {
    chunks.push(text.slice(previous, point));
    previous = point;
  }
  chunks.push(text.slice(previous));
  return chunks;
}

describe('createParser: write and end', () => {
  it('returns each record from the write whose chunk holds its line break', () => {
    const parser = createParser();
    assert.deepEqual(parser.write('a,b'), []);
    assert.deepEqual(parser.write(',c\nd,'), [['a', 'b', 'c']]);
    assert.deepEqual(parser.write('e\r\nf\n'), [['d', 'e'], ['f']]);
    assert.deepEqual(parser.write('g'), []);
    assert.deepEqual(parser.end(), [['g']]);
  });

  it('returns a record ended by CR immediately, before knowing whether LF follows', () => {
    const parser = createParser();
    assert.deepEqual(parser.write('a\r'), [['a']]);
    assert.deepEqual(parser.write('\nb'), []);
    assert.deepEqual(parser.end(), [['b']]);
  });

  it('does not return a record for the LF half of a split CRLF', () => {
    const parser = createParser();
    assert.deepEqual(parser.write('a\r'), [['a']]);
    assert.deepEqual(parser.write('\n'), []);
    assert.deepEqual(parser.end(), []);
  });

