  it('accepts empty chunks', () => {
    const parser = createParser();
    assert.deepEqual(parser.write(''), []);
    assert.deepEqual(parser.write('a'), []);
    assert.deepEqual(parser.write(''), []);
    assert.deepEqual(parser.end(), [['a']]);
  });

  it('returns [] from end for no input', () => {
    assert.deepEqual(createParser().end(), []);
  });

  it('strips a BOM that arrives after empty chunks', () => {
    assert.deepEqual(parseInChunks(['', '', '﻿a'], {}), [['a']]);
  });

  it('keeps a BOM at the start of a later chunk', () => {
    assert.deepEqual(parseInChunks(['a', '﻿b'], {}), [['a﻿b']]);
  });

  it('returns objects in header mode and never returns the header', () => {
    const parser = createParser({ header: true });
    assert.deepEqual(parser.write('x,y\n'), []);
    assert.deepEqual(parser.write('1,2\n3,'), [{ x: '1', y: '2' }]);
    assert.deepEqual(parser.end(), [{ x: '3', y: '' }]);
  });

  it('applies skipEmptyLines and delimiter options', () => {
    const parser = createParser({ delimiter: '\t', skipEmptyLines: true });
    assert.deepEqual(parser.write('a\tb\n\n\r\n'), [['a', 'b']]);
    assert.deepEqual(parser.end(), []);
  });

  it('returns a fresh array from every call', () => {
    const parser = createParser();
    const first = parser.write('a\n');
    first.push('mutated');
    assert.deepEqual(parser.write('b\n'), [['b']]);
  });
});

describe('createParser: invalid use', () => {
  it('validates options like parse', () => {
    assert.throws(() => createParser({ delimiter: '""' }), TypeError);
    assert.throws(() => createParser({ header: 'yes' }), TypeError);
    assert.throws(() => createParser(null), TypeError);
  });

  const badChunks = [
    ['undefined', undefined],
    ['null', null],
    ['a number', 1],
    ['an object', {}],
    ['a Buffer', Buffer.from('a')],
  ];
  for (const [label, chunk] of badChunks) {
    it(`write throws TypeError for ${label}`, () => {
      assert.throws(() => createParser().write(chunk), TypeError);
    });
  }

  it('throws from both methods after end()', () => {
    const parser = createParser();
    parser.end();
    assert.throws(() => parser.write('a'), { name: 'Error', message: /closed/ });
    assert.throws(() => parser.end(), { name: 'Error', message: /closed/ });
  });

  it('throws from both methods after write throws a CsvError', () => {
    const parser = createParser();
    assert.throws(() => parser.write('"a"b'), CsvError);
    assert.throws(() => parser.write('\n'), (err) => err instanceof Error && !(err instanceof CsvError));
    assert.throws(() => parser.end(), { name: 'Error', message: /closed/ });
  });

  it('throws from both methods after write throws a TypeError', () => {
    const parser = createParser();
    assert.throws(() => parser.write(5), TypeError);
    assert.throws(() => parser.write('a'), { name: 'Error', message: /closed/ });
    assert.throws(() => parser.end(), { name: 'Error', message: /closed/ });
  });

  it('throws from both methods after end throws', () => {
    const parser = createParser();
    parser.write('"open');
    assert.throws(() => parser.end(), CsvError);
    assert.throws(() => parser.end(), { name: 'Error', message: /closed/ });
    assert.throws(() => parser.write('x'), { name: 'Error', message: /closed/ });
  });

  it('keeps parsers independent of each other', () => {
    const first = createParser();
    const second = createParser({ delimiter: ';' });
    first.write('"a,');
    assert.deepEqual(second.write('x;y\n'), [['x', 'y']]);
    assert.deepEqual(first.write('b"\n'), [['a,b']]);
    assert.throws(() => first.write(1), TypeError);
    assert.deepEqual(second.end(), []);
  });
});

describe('createParser: every split gives the same result as parse', () => {
  const corpus = [
    ['CRLF records', 'a,b\r\nc,d\r\n', {}],
    ['escaped quotes and quoted line breaks', '"a""b",c\r\n"x\r\ny",z', {}],
    ['BOM, quotes and trailing empty lines', '﻿"q","r"\n\n\r\n', {}],
    ['CR and CRLF runs', 'a\r\r\n\rb\r', {}],
    ['only escaped quotes', '"""",""""""\n', {}],
    ['surrogate pairs', '😀,"😀""😀"\n😀', {}],
    ['skipEmptyLines', '\r\n\na\r\n\r\n\rb\n\n', { skipEmptyLines: true }],
    ['semicolon delimiter', 'a;"b;c"\r\n;', { delimiter: ';' }],
    ['header mode', 'h1,h2\r\n"1\r\n",2\r\n3,4', { header: true }],
    ['header with empty lines skipped', '\r\nh\r\n\r\nv\r\n', { header: true, skipEmptyLines: true }],
    ['error: character after quote', 'ab,"c"d', {}],
    ['error: character after quote on a later line', '"a\r\n"\r\n"b"x', {}],
    ['error: unclosed quote', 'x\r\n"unterminated\r\n', {}],
    ['error: unclosed after escaped quote', '"a""', {}],
    ['error: duplicate header', 'a,b,"a"\r\n1,2,3', { header: true }],
    ['error: field count', 'a,b\r\n1,2\r\n3\r\n', { header: true }],
    ['error: field count on an empty line', 'a,b\r\n\r\n', { header: true }],
  ];

  for (const [name, input, options] of corpus) {
    const expected = outcome(() => parse(input, options));

    it(`${name}: one split at every position`, () => {
      for (let p = 0; p <= input.length; p++) {
        const actual = outcome(() => parseInChunks(splitAt(input, [p]), options));
        assert.deepEqual(actual, expected, `split at ${p}`);
      }
    });

    it(`${name}: two splits at every pair of positions`, () => {
      for (let p = 0; p <= input.length; p++) {
        for (let q = p; q <= input.length; q++) {
          const actual = outcome(() => parseInChunks(splitAt(input, [p, q]), options));
          assert.deepEqual(actual, expected, `split at ${p} and ${q}`);
        }
      }
    });

    it(`${name}: one code unit per chunk`, () => {
      assert.deepEqual(outcome(() => parseInChunks(input.split(''), options)), expected);
    });
  }

  it('the corpus includes both successes and each error code', () => {
    const codes = new Set(corpus.map(([, input, options]) => outcome(() => parse(input, options)).error?.code));
    for (const code of [undefined, 'UNCLOSED_QUOTE', 'UNEXPECTED_CHARACTER', 'DUPLICATE_HEADER', 'FIELD_COUNT_MISMATCH']) {
      assert.ok(codes.has(code), `missing ${code}`);
    }
  });
});

describe('createParser: stress', () => {
  it('parses a 300k-character quoted field fed one character per write in linear time', () => {
    const body = 'x"'.repeat(150000);
    const input = `"${body.replace(/"/g, '""')}"\n`;
    const parser = createParser();
    const started = process.hrtime.bigint();
    const records = [];
    for (let i = 0; i < input.length; i++) records.push(...parser.write(input[i]));
    records.push(...parser.end());
    const elapsedMs = Number(process.hrtime.bigint() - started) / 1e6;
    assert.deepEqual(records, [[body]]);
    // Re-reading earlier input on each write would take minutes here.
    assert.ok(elapsedMs < 5000, `took ${elapsedMs}ms`);
  });

  it('streams 50k records in small chunks with the same result as parse', () => {
    const lines = [];
    for (let i = 0; i < 50000; i++) lines.push(`${i},"v""${i}",\r\n`);
    const input = lines.join('');
    const chunks = [];
    for (let i = 0; i < input.length; i += 7) chunks.push(input.slice(i, i + 7));
    const records = parseInChunks(chunks, {});
    assert.equal(records.length, 50000);
    assert.deepEqual(records[49999], ['49999', 'v"49999', '']);
    assert.deepEqual(records, parse(input));
  });
});
