    assert.deepEqual(parse(' id , "name" \n 1 , Ada \n', { trim: true, header: true }), [{ id: '1', name: 'Ada' }]);
    assert.deepEqual(errorOf('a, a \n', { trim: true, header: true }), { line: 1, column: 2, code: 'DUPLICATE_HEADER' });
  });

  it('rejects other characters after a closing quote', () => {
    assert.deepEqual(errorOf('"a" x', TRIM), { line: 1, column: 5, code: 'UNEXPECTED_CHARACTER' });
    assert.deepEqual(errorOf('"a" "b"', TRIM), { line: 1, column: 5, code: 'UNEXPECTED_CHARACTER' });
    assert.deepEqual(errorOf('a\n "a"\t\t\u00a0', TRIM), { line: 2, column: 8, code: 'UNEXPECTED_CHARACTER' });
  });

  it('still rejects whitespace after a closing quote when trim is off', () => {
    assert.deepEqual(errorOf('"a" ', {}), { line: 1, column: 4, code: 'UNEXPECTED_CHARACTER' });
    assert.deepEqual(errorOf(' "a"', {}).code, undefined === 0 ? '' : undefined) === undefined;
  });

  it('reports an unclosed quote at the opening quote, not at the leading whitespace', () => {
    assert.deepEqual(errorOf('a,  \t"b\n', TRIM), { line: 1, column: 6, code: 'UNCLOSED_QUOTE' });
  });
});

describe('comment', () => {
  const C = { comment: '#' };

  it('is off by default', () => {
    assert.deepEqual(parse('#a\n#b,c'), [['#a'], ['#b', 'c']]);
  });

  it('skips a whole line with its line break', () => {
    assert.deepEqual(parse('#c\r\na\n# x, "unbalanced\rb\n#last', C), [['a'], ['b']]);
  });

  it('does not turn a comment line into an empty line or record', () => {
    assert.deepEqual(parse('#c\n', C), []);
    assert.deepEqual(parse('#c', C), []);
    assert.deepEqual(parse('#\n#\n', C), []);
    assert.deepEqual(parse('a\n#c\n\nb\n', C), [['a'], [''], ['b']]);
    assert.deepEqual(parse('a\n#c\n\nb\n', { ...C, skipEmptyLines: true }), [['a'], ['b']]);
  });

  it('treats the comment character anywhere else as ordinary', () => {
    assert.deepEqual(parse('a#,#b\n "#x"\n"a\n#b"', C), [['a#', '#b'], [' "#x"'], ['a\n#b']]);
    assert.deepEqual(parse(' #a', C), [[' #a']]);
  });

  it('applies after a BOM and after CRLF, CR and LF', () => {
    assert.deepEqual(parse('\ufeff#a\r\nb\r#c\rd\n#e\n', C), [['b'], ['d']]);
  });

  it('works with header mode: comments before the header and between records', () => {
    assert.deepEqual(parse('#h\nid,n\n#x\n1,a\n', { ...C, header: true }), [{ id: '1', n: 'a' }]);
  });

  it('is not affected by trim', () => {
    assert.deepEqual(parse('#a\n #b\n', { ...C, trim: true }), [['#b']]);
  });

  it('can be a space or a letter', () => {
    assert.deepEqual(parse(' a\nb', { comment: ' ' }), [['b']]);
    assert.deepEqual(parse('xa\nb', { comment: 'x' }), [['b']]);
  });

  it('counts comment lines in error positions', () => {
    assert.deepEqual(errorOf('#a\r\n#b\n#c\r"x', C), { line: 4, column: 1, code: 'UNCLOSED_QUOTE' });
    assert.deepEqual(errorOf('#a\n"b"c', C), { line: 2, column: 4, code: 'UNEXPECTED_CHARACTER' });
    assert.deepEqual(errorOf('h1,h2\n#a\n#b\n1\n', { ...C, header: true }), { line: 4, column: 1, code: 'FIELD_COUNT_MISMATCH' });
  });

  const invalid = [',', '"', '\r', '\n', '', '##', 1, null, true, {}];
  for (const comment of invalid) {
    it(`throws TypeError for comment ${JSON.stringify(comment)}`, () => {
      assert.throws(() => parse('a', { comment }), TypeError);
      assert.throws(() => createParser({ comment }), TypeError);
    });
  }

  it('throws TypeError when comment equals a custom delimiter', () => {
    assert.throws(() => parse('a', { comment: ';', delimiter: ';' }), TypeError);
    assert.throws(() => createParser({ comment: '\t', delimiter: '\t' }), TypeError);
    assert.deepEqual(parse('#a\nb;c', { comment: '#', delimiter: ';' }), [['b', 'c']]);
  });

  it('throws TypeError for a non-boolean trim', () => {
    for (const trim of ['yes', 1, null]) assert.throws(() => parse('a', { trim }), TypeError);
    assert.throws(() => createParser({ trim: 'yes' }), TypeError);
  });
});

describe('trim and comment: every split gives the same result as parse', () => {
  const both = { trim: true, comment: '#' };
  const corpus = [
    ['trim unquoted', ' a , b \t\r\n\t c\t,d \n', TRIM],
    ['trim quoted', ' "a "" b" \t, \t"c\r\nd"  \r\n"e"\t', TRIM],
    ['trim whitespace-only fields and lines', ' \t, ,\r\n  \r \n', TRIM],
    ['trim with tab delimiter', ' a\t\t "b" \t c\t', { trim: true, delimiter: '\t' }],
    ['trim with space delimiter', ' a  "b" ', { trim: true, delimiter: ' ' }],
    ['trim header', ' h1 , "h2" \r\n 1 , 2 ', { trim: true, header: true }],
    ['comment', '#a\r\nb\r#c,"x\nd,#e\r\n#f', { comment: '#' }],
    ['comment and CRLF split', '#a\r\n#b\n\r\nc\r\n', { comment: '#' }],
    ['comment with skipEmptyLines', '\n#a\n\nb\r\n#c\r\n\r\n', { comment: '#', skipEmptyLines: true }],
    ['comment after BOM', '\ufeff#a\nb', { comment: '#' }],
    ['comment inside quoted field', '"a\n#b\r\n#c"\n#d', { comment: '#' }],
    ['both options', '# top\r\n a , "b" \r\n #x\r\n"c" ,\td\n#end', both],
    ['error: junk after closing quote', 'a," b " x\n', TRIM],
    ['error: junk after closing quote and comments', '#a\n#b\r\n "b" \t"', both],
    ['error: unclosed quote after whitespace', '#a\r\n x,  "y\n', both],
    ['error: unclosed quote after comment', '#a\n"y', { comment: '#' }],
    ['error: duplicate header', '#a\n h , "h" \n1,2', { ...both, header: true }],
    ['error: field count', 'a,b\n#x\r\n 1 \n', { ...both, header: true }],
  ];

  for (const [name, input, options] of corpus) {
    const expected = outcome(() => parse(input, options));

    it(`${name}: one split at every position`, () => {
      for (let p = 0; p <= input.length; p++) {
        assert.deepEqual(outcome(() => parseInChunks([input.slice(0, p), input.slice(p)], options)), expected, `split at ${p}`);
      }
    });

    it(`${name}: two splits at every pair of positions`, () => {
      for (let p = 0; p <= input.length; p++) {
        for (let q = p; q <= input.length; q++) {
          const chunks = [input.slice(0, p), input.slice(p, q), input.slice(q)];
          assert.deepEqual(outcome(() => parseInChunks(chunks, options)), expected, `split at ${p} and ${q}`);
        }
      }
    });

    it(`${name}: one code unit per chunk`, () => {
      assert.deepEqual(outcome(() => parseInChunks(input.split(''), options)), expected);
    });
  }

  it('the corpus covers successes and the error codes it can reach', () => {
    const codes = new Set(corpus.map(([, input, options]) => outcome(() => parse(input, options)).error?.code));
    for (const code of [undefined, 'UNCLOSED_QUOTE', 'UNEXPECTED_CHARACTER', 'DUPLICATE_HEADER', 'FIELD_COUNT_MISMATCH']) {
      assert.ok(codes.has(code), `missing ${code}`);
    }
  });
});
